const depth=title=>/^(Entity:|Guide:|Provider:|Format:|Intelligence:|Industry:)/.test(title)||['Intelligence Home','Providers Home','Industries Home'].includes(title)?'../':'';
const fixedCanonicalPaths=new Map([['Home',''],['Intelligence Home','intelligence/'],['Providers Home','providers/'],['Industries Home','industries/'],['Expansion Reconciliation Report','reconciliation-report.html']]);
const canonicalPath=title=>fixedCanonicalPaths.has(title)?fixedCanonicalPaths.get(title):title.startsWith('Entity:')?`entities/${entities.find(entity=>entity.name===title.slice(8))?.slug||slug(title.slice(8))}.html`:title.startsWith('Guide:')?`guides/${cfoGuides.find(guide=>guide.title===title.slice(7))?.slug||slug(title.slice(7))}.html`:title.startsWith('Provider:')?`providers/${slug(title.slice(9))}.html`:title.startsWith('Format:')?`formats/${slug(title.slice(7))}.html`:title.startsWith('Intelligence:')?`intelligence/${slug(title.slice(13))}.html`:title.startsWith('Industry:')?`industries/${slug(title.slice(9))}.html`:`${slug(title)}.html`;
const labelForTitle=title=>title.replace(/^(Entity|Guide|Provider|Format|Intelligence|Industry):\s*/, '').replace(/ Home$/,'');
const breadcrumbParents=title=>title.startsWith('Provider:')?[['Providers','providers/']]:title.startsWith('Intelligence:')?[['Intelligence','intelligence/']]:title.startsWith('Industry:')?[['Industries','industries/']]:title.startsWith('Guide:')?[['Research','cfo-guides.html']]:title.endsWith(' Ecosystem')&&title!=='CXO Ecosystems'?[['CXO Ecosystems','cxo-ecosystems.html']]:[];
const breadcrumbs=title=>{if(title==='Home')return {html:'',json:null};const items=[['Home',''],...breadcrumbParents(title),[labelForTitle(title),canonicalPath(title)]];const prefix=depth(title);const html=`<nav class="crumb" aria-label="Breadcrumb">${items.map(([label,url],index)=>index===items.length-1?`<span aria-current="page">${esc(label)}</span>`:`<a href="${prefix}${url||'index.html'}">${esc(label)}</a>`).join(' / ')}</nav>`;const json={'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:items.map(([name,url],index)=>({'@type':'ListItem',position:index+1,name,item:`https://openfutureforum.github.io/cxo-ecosystem-index/${url}`}))};return {html,json};};
const modifiedFor=title=>{if(title.startsWith('Entity:')){const entity=entities.find(item=>item.name===title.slice(8));return entity?.facts?.map(fact=>fact.last_verified).filter(Boolean).sort().at(-1)||entity?.last_verified||null;}if(title.startsWith('Guide:'))return cfoGuides.find(guide=>guide.title===title.slice(7))?.updated||null;if(['Methodology','Expansion Reconciliation Report','v050 Report'].includes(title))return null;return CALCULATED_AT;};
const shell=(title,body,description='Open-source intelligence for the C-suite.',pageTitle=title)=>{const canonical=`https://openfutureforum.github.io/cxo-ecosystem-index/${canonicalPath(title)}`;const displayTitle=title==='Home'?'CXO Ecosystem Index | C-Suite Companies, Communities & Advisors':`${pageTitle} | CXO Ecosystem Index`;const crumb=breadcrumbs(title);const modified=modifiedFor(title);const modifiedProperties=modified?{dateModified:modified}:{};const pageLd=title==='Home'?{'@context':'https://schema.org','@graph':[{'@type':'WebSite',name:'CXO Ecosystem Index',url:canonical,description},{'@type':'DataCatalog',name:'CXO Ecosystem Index',url:canonical,dataset:'https://openfutureforum.github.io/cxo-ecosystem-index/data.html',...modifiedProperties}]}:{'@context':'https://schema.org','@graph':[{'@type':'WebPage',name:pageTitle,url:canonical,description,...modifiedProperties},...(crumb.json?[crumb.json]:[])]};const modifiedMeta=modified?`<meta name="last-modified" content="${modified}">`:'';return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(displayTitle)}</title><meta name="description" content="${esc(description)}">${modifiedMeta}<link rel="canonical" href="${canonical}"><meta property="og:title" content="${esc(displayTitle)}"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="website"><link rel="stylesheet" href="${depth(title)}assets/${styleAsset}"><script type="application/ld+json">${JSON.stringify(pageLd)}</script></head><body><header><a class="brand" href="${depth(title)}index.html"><b>CXO</b> Ecosystem Index</a><nav><a href="${depth(title)}index.html#explore">Explore</a><a href="${depth(title)}cxo-ecosystems.html">CXO Ecosystems</a><a href="${depth(title)}providers/">Providers</a><a href="${depth(title)}intelligence/">Intelligence</a><a href="${depth(title)}cfo-guides.html">Research</a><a href="${depth(title)}data.html">Data</a><a href="${depth(title)}methodology.html">Methodology</a></nav></header><main>${crumb.html}${body}</main><footer><p>Independent structured index maintained by Open Future Forum. Inclusion does not imply endorsement.</p><p>Dataset ${releaseLabel} · Schema ${SCHEMA_VERSION} · Updated ${CALCULATED_AT}</p><p><a href="https://openfutureforum.github.io/executive-communities-index/">Executive Communities Index</a> · <a href="https://openfutureforum.github.io/executive-community-playbook/">Executive Community Playbook</a></p></footer></body></html>`;};

