for(const entity of entities){
 const facts=[['Organization type',entity.entity_type],['Common names / aliases',(entity.aliases||[]).join(', ')],['Parent company',entity.parent_company],['Relationship notes',entity.relationship_notes],['Editorial research priority',entity.editorial_priority],['Serves',entity.cxo_roles.join(', ')],['Provider types',entity.categories.join(', ')],['Industries',(entity.industries||[]).join(', ')],['Geography',entity.geographies.join(', ')],['Verification',entity.verification_status],['Last verified',entity.last_verified]].filter(([,value])=>value);
 const sections=[['Community formats',labels('community_formats',entity.community_formats)],['Event formats',labels('event_formats',entity.event_formats)],['Research & intelligence',labels('intelligence_types',entity.intelligence_types)],['Resources',labels('resource_types',entity.resource_types)],['Executive needs',labels('executive_needs',entity.executive_needs)],['Topics',labels('topics',entity.topics)],['Additional audiences',labels('audiences',entity.audiences)]];
 const semanticSections=sections.filter(([,values])=>values.length).map(([heading,values])=>`<section><h2>${heading}</h2><div class="tags large">${values.map(value=>`<span>${esc(value)}</span>`).join('')}</div></section>`).join('');
 const sources=[...entity.sources.map(x=>({id:x.id,url:x.url,title:x.title,detail:`${x.publisher} · accessed ${x.accessed_date} · supports ${x.supports.join(', ')}`})),...entity.classification_evidence.map((x,index)=>({id:`classification-source-${index+1}`,url:x.url,title:x.title,detail:`classification evidence · supports ${x.supports.join(', ')}`}))];
 const sourceList=sources.map(source=>`<li id="${esc(source.id||'classification-source')}"><a href="${esc(source.url)}">${esc(source.title)}</a><span>${esc(source.detail)}</span></li>`).join('');
 const factRows=(entity.facts||[]).map(fact=>`<tr><td>${esc(fact.field.replaceAll('_',' '))}</td><td>${esc(factDisplay(fact))}</td><td>${fact.source_ids.map(id=>`<a href="#${esc(id)}">${esc(id)}</a>`).join(', ')}</td><td>${esc(fact.as_of_date||fact.last_verified)}</td></tr>`).join('');
 const relationRows=(relationsBySubject[entity.id]||[]).map(relation=>{const related=byId.get(relation.object_entity_id);return `<tr><td>${esc(relation.predicate.replaceAll('_',' '))}</td><td><a href="${related.slug}.html">${esc(related.name)}</a></td><td>${esc(relation.status)}</td><td>${esc(relation.as_of_date||relation.valid_from||'')}</td><td>${esc(relation.source_ids.join(', '))}${relation.derived_reciprocal?' · reciprocal derived from sourced edge':''}</td></tr>`;}).join('');
 const jsonld=JSON.stringify({'@context':'https://schema.org','@type':'Organization',name:entity.name,alternateName:entity.aliases||[],url:entity.website,description:entity.description,areaServed:entity.geographies,knowsAbout:[...new Set([...entity.categories,...labels('topics',entity.topics),...labels('intelligence_types',entity.intelligence_types),...labels('executive_needs',entity.executive_needs)])],audience:[...entity.cxo_roles.map(role=>({'@type':'Audience',audienceType:role})),...labels('audiences',entity.audiences).map(audienceType=>({'@type':'Audience',audienceType}))],parentOrganization:entity.parent_company?{'@type':'Organization',name:entity.parent_company}:undefined});
 const providerLinks=entity.provider_types.filter(id=>providerGroups.some(group=>group.id===id)).map(id=>`<a href="../providers/${id}.html">${esc(termTitle(id))}</a>`);
 const roleHref=role=>role==='CFO'?'cfo-ecosystem.html':role==='CIO'||role==='CTO'?'cio-cto-ecosystem.html':role==='CLO'||role==='General Counsel'?'clo-general-counsel-ecosystem.html':`${slug(role)}-ecosystem.html`;
 const roleDiscovery=[...new Map(entity.cxo_roles.map(role=>[roleHref(role),role])).entries()].map(([href,role])=>`<a href="../${href}">${esc(role)}</a>`);
 const mapLinks=intelligence.market_maps.filter(map=>map.entity_ids.includes(entity.id)).map(map=>`<a href="../intelligence/${map.id}.html">${esc(map.title)}</a>`);
 const relatedLinks=[...providerLinks,...roleDiscovery,...mapLinks];
 const body=`<section class="entity-head"><div class="eyebrow">${esc(entity.entity_type)}</div><h1>${esc(entity.name)}</h1><p>${esc(entity.description)}</p><a class="site-link" href="${esc(entity.website)}">Official website ↗</a></section><section class="entity-layout"><div><h2>Structured facts</h2><dl>${facts.map(([a,b])=>`<dt>${a}</dt><dd>${esc(b)}</dd>`).join('')}</dl></div><div><h2>Inclusion basis</h2><p>${esc(entity.inclusion_basis.join(' '))}</p><h2>Products and services</h2><p>${esc([...(entity.products||[]),...(entity.services||[])].join(', ')||'Not recorded.')}</p></div></section><div class="semantic-sections">${semanticSections}</div><p><small>${(semanticRelationsBySubject[entity.id]||[]).length} evidence-linked semantic relationships are available in the <a href="../data/semantic-relationships.json">semantic relationship export</a>.</small></p>${relatedLinks.length?`<section><h2>Related discovery</h2><div class="download">${relatedLinks.join('')}</div></section>`:''}<section><h2>Source-linked facts</h2><p>${entity.facts.length} structured facts are linked to the supporting source record and verification or as-of date.</p><div class="table-wrap"><table><thead><tr><th>Field</th><th>Value</th><th>Source ID</th><th>As of / verified</th></tr></thead><tbody>${factRows}</tbody></table></div></section>${relationRows?`<section><h2>Ecosystem Relationships</h2><div class="table-wrap"><table><thead><tr><th>Relationship</th><th>Organization</th><th>Status</th><th>Date</th><th>Provenance</th></tr></thead><tbody>${relationRows}</tbody></table></div></section>`:''}<section><h2>Sources</h2><ul class="sources">${sourceList}</ul></section><script type="application/ld+json">${jsonld}</script>`;
 await write(`docs/entities/${entity.slug}.html`,shell(`Entity: ${entity.name}`,body,entity.description,`${entity.name} | ${entity.categories.slice(0,2).join(' & ')}`));
}

const cfoEntities=entities.filter(entity=>entity.cxo_roles.includes('CFO'));
const topicList=items=>`<div class="topic-grid">${items.map(item=>`<span>${esc(typeof item==='string'?item:item.name)}</span>`).join('')}</div>`;
const roleMappingById=new Map(roleMappings.mappings.map(mapping=>[mapping.id,mapping]));
const mappingLens=id=>{const mapping=roleMappingById.get(id);if(!mapping)return '';const groups=[['Community formats','community_formats',mapping.community_format_ids],['Event formats','event_formats',mapping.event_format_ids],['Research & intelligence','intelligence_types',mapping.intelligence_type_ids],['Executive needs','executive_needs',mapping.executive_need_ids],['Topics','topics',mapping.topic_ids],['Audiences','audiences',mapping.audience_ids]].filter(([,dimension,ids])=>ids?.length).map(([heading,dimension,ids])=>`<div><h3>${heading}</h3><div class="tags large">${labels(dimension,ids).map(label=>`<span>${esc(label)}</span>`).join('')}</div></div>`).join('');return `<section><h2>Taxonomy lens</h2><p>This lens identifies controlled concepts relevant to the ${esc(mapping.label)}. It does not claim that every listed organization offers every format, resource, or outcome.</p><div class="semantic-sections">${groups}</div></section>`;};
await write('docs/cfo-ecosystem.html',shell('CFO Ecosystem',`<section class="prose wide"><div class="eyebrow">EXPLORE BY CXO</div><h1>CFO Ecosystem</h1><p>A structured view of the companies, advisors, capital providers, communities, and technology platforms serving chief financial officers and finance organizations.</p><div class="stats compact"><div><strong>${cfoEntities.length}</strong><span>CFO-relevant entities</span></div><div><strong>${new Set(cfoEntities.flatMap(e=>e.categories)).size}</strong><span>Provider categories</span></div><div><strong>${new Set(cfoEntities.flatMap(e=>e.geographies)).size}</strong><span>Markets represented</span></div></div>${mappingLens('cfo')}<h2>Operating contexts</h2>${topicList(cfoTaxonomy.contexts)}<h2>Finance functions</h2>${topicList(cfoTaxonomy.functional_topics)}<h2>Systems and transformation</h2>${topicList(cfoTaxonomy.systems_topics)}<h2>Decision resources</h2>${topicList(cfoTaxonomy.decision_resources)}<h2>Indexed organizations</h2><div class="grid">${cfoEntities.map(entityCard).join('')}</div></section>`,'Structured intelligence on providers, systems, capital, communities, and advisors serving CFOs.'));
