await write('docs/providers/index.html',shell('Providers Home',`<section class="prose wide"><div class="eyebrow">PROVIDER DISCOVERY</div><h1>Provider Intelligence</h1><p>Substantial provider cohorts with source coverage, CXO-role distribution, adjacent-category analysis, and canonical entity records.</p><div class="grid">${providerHubCards}</div></section>`,'Provider intelligence across the C-suite ecosystem.','Providers'));

const intelligenceCard=(item,type)=>{const href=type==='Comparison'?`compare-${item.comparison_id}.html`:`${item.id}.html`;return `<article class="card"><div class="eyebrow">${esc(type)}</div><h3><a href="${href}">${esc(item.title)}</a></h3><p>${type==='Market Map'?`${item.total_entities} canonical entities across ${item.buckets.length} documented layers.`:type==='Comparison'?`${item.entity_ids.length} organizations compared using canonical fields.`:`Coverage-aware analysis generated from dataset version ${item.dataset_version}.`}</p></article>`;};
