for(const benchmark of intelligence.benchmarks.filter(item=>item.id!=='data-quality')){
 let content='';
 if(benchmark.metrics)content=`<div class="table-wrap"><table><thead><tr><th>Scope</th><th>Numerator</th><th>Known denominator</th><th>Unknown</th><th>Coverage</th><th>Result</th></tr></thead><tbody>${benchmark.metrics.map(metric=>`<tr><td>${esc(metric.name)}</td><td>${metric.numerator}</td><td>${metric.denominator}</td><td>${metric.unknown_count}</td><td>${Math.round(100*metric.coverage)}%</td><td>${metric.notes||`${Math.round(100*metric.value)}% of known records`}</td></tr>`).join('')}</tbody></table></div>`;
 else if(benchmark.role_distribution)content=`<div class="stats compact"><div><strong>${benchmark.exactly_one}</strong><span>Exactly one CXO role</span></div><div><strong>${benchmark.two_to_three}</strong><span>Two to three roles</span></div><div><strong>${benchmark.four_plus}</strong><span>Four or more roles</span></div></div><h2>Role distribution</h2><p>${benchmark.role_distribution.map(item=>`${esc(item.role)} ${item.count}`).join(' · ')}</p>`;
 else content=`<blockquote><b>${benchmark.status==='insufficient coverage'?'Coverage insufficient for a reliable headline benchmark.':'Usable coverage.'}</b> ${benchmark.known_count} known records and ${benchmark.unknown_count} unknown records; ${Math.round(100*benchmark.coverage)}% coverage.</blockquote>`;
 const body=`<section class="prose wide"><div class="eyebrow">DATASET BENCHMARK</div><h1>${esc(benchmark.title)}</h1>${content}<h2>Methodology</h2><p>${esc(benchmark.method||'Calculated from canonical structured fields. Unknown values are not counted as false.')}</p><p><b>Dataset:</b> ${benchmark.dataset_version} · <b>Calculated:</b> ${benchmark.calculated_at}</p><p><a href="../data/benchmarks.json">Download benchmark JSON</a></p></section>`;
 await write(`docs/intelligence/${benchmark.id}.html`,shell(`Intelligence: ${benchmark.id}`,body,`Coverage-aware ${benchmark.title.toLowerCase()} from the CXO Ecosystem Index.`,benchmark.title));
}

