const qualityHtml=shell('Data Quality',`<section class="prose wide"><div class="eyebrow">PUBLIC DATA QUALITY DASHBOARD</div><h1>Data Quality</h1><div class="stats compact"><div><strong>${quality.total_entities}</strong><span>Organizations</span></div><div><strong>${quality.total_facts}</strong><span>Sourced facts</span></div><div><strong>${sourceRegistry.length}</strong><span>Canonical sources</span></div><div><strong>${knowledgeGraph.sourced_relationship_count}</strong><span>Sourced relationships</span></div><div><strong>${knowledgeGraph.derived_reciprocal_count}</strong><span>Derived relationships</span></div><div><strong>${derivedMetricCount}</strong><span>Derived metrics</span></div></div><h2>Coverage and freshness</h2><div class="table-wrap"><table><tbody><tr><th>Verified entities</th><td>${quality.verified_entities}</td></tr><tr><th>Average sourced facts/entity</th><td>${quality.average_facts_per_entity}</td></tr><tr><th>Median sourced facts/entity</th><td>${quality.median_facts_per_entity}</td></tr><tr><th>Entities with 5+ facts</th><td>${quality.entities_with_5_plus}</td></tr><tr><th>Entities with 10+ facts</th><td>${quality.entities_with_10_plus}</td></tr><tr><th>Entities with 20+ facts</th><td>${quality.entities_with_20_plus}</td></tr><tr><th>Primary-source fact coverage</th><td>${Math.round(100*sourceMetrics.primary_fact_percentage)}%</td></tr><tr><th>Volatile facts with as-of date</th><td>${quality.volatile_facts_with_as_of_date}</td></tr><tr><th>Stale facts</th><td>${quality.stale_facts}</td></tr><tr><th>Conflicting facts</th><td>${quality.conflicting_facts}</td></tr><tr><th>Missing headquarters</th><td>${quality.missing_headquarters}</td></tr><tr><th>Missing founding year</th><td>${quality.missing_founding_year}</td></tr></tbody></table></div><h2>Fact-density distribution</h2><div class="table-wrap"><table><thead><tr><th>Facts per entity</th><th>Entities</th></tr></thead><tbody>${quality.fact_distribution.map(([label,count])=>`<tr><td>${label}</td><td>${count}</td></tr>`).join('')}</tbody></table></div><h2>Methodology</h2><p>Generated from canonical facts, sources, relationships and derived intelligence in dataset ${quality.dataset_version} on ${quality.calculated_at}. Missing values are reported rather than inferred.</p><p><a href="data/data-quality.json">Download quality JSON</a></p></section>`,'Public coverage, verification, source quality, freshness and fact-density metrics.');
