const taxonomySection=(heading,items)=>`<section><h2>${heading}</h2><div class="table-wrap"><table><thead><tr><th>Stable ID</th><th>Term</th><th>Neutral definition</th></tr></thead><tbody>${items.map(item=>`<tr><td><code>${esc(item.id)}</code></td><td>${esc(item.label)}</td><td>${esc(item.definition)}</td></tr>`).join('')}</tbody></table></div></section>`;
const entityAnswerList=items=>items.length?`<ul>${items.map(entity=>`<li><a href="entities/${entity.slug}.html">${esc(entity.name)}</a></li>`).join('')}</ul>`:'<p>No evidence-backed organization is currently classified for this query.</p>';
const executiveCommunityDefinition=semantic.community_formats.find(item=>item.id==='executive-community').definition;
