const aliasRows=taxonomyAliases.aliases.map(item=>`<tr><td>${esc(item.alias)}</td><td>${esc(item.dimension.replaceAll('_',' '))}</td><td><code>${esc(item.canonical_id)}</code></td></tr>`).join('');
const mappingCards=roleMappings.mappings.map(mapping=>`<article class="card"><h3>${esc(mapping.label)}</h3><p>${mapping.community_format_ids.length} community formats · ${mapping.event_format_ids.length} event formats · ${mapping.intelligence_type_ids.length} intelligence types · ${mapping.executive_need_ids.length} needs · ${mapping.topic_ids.length} topics.</p></article>`).join('');
const faqLd=JSON.stringify({'@context':'https://schema.org','@type':'FAQPage',mainEntity:[['What is an executive community?',executiveCommunityDefinition],['What organizations serve CFOs?',`${cfoEntities.length} canonical organizations are classified as serving CFOs in dataset ${DATASET_VERSION}.`],['Which organizations run CISO events?',`${cisoEventOrganizations.length} organizations have both a CISO role association and at least one evidence-backed event format.`],['Which organizations publish executive benchmarks?',`${benchmarkPublishers.length} organizations have an evidence-backed benchmark classification.`],['Which organizations serve private equity operating partners?',`${operatingPartnerOrganizations.length} organizations have an evidence-backed operating-partner audience classification.`],['Which organizations provide CMO networks?',`${cmoNetworkOrganizations.length} organizations have both a CMO role association and an evidence-backed community format.`],['What types of executive events exist?',`${semantic.event_formats.length} controlled event-format terms are defined in dataset ${DATASET_VERSION}.`],['Which organizations provide executive research?',`${executiveResearchPublishers.length} organizations have an evidence-backed executive-research classification.`]].map(([name,text])=>({'@type':'Question',name,acceptedAnswer:{'@type':'Answer',text}}))});
const taxonomyBody=`<section class="prose wide"><div class="eyebrow">CONTROLLED KNOWLEDGE MODEL</div><h1>CXO formats, intelligence and outcomes taxonomy</h1><p>The Index maps organizations across executive roles, provider types, ongoing community formats, time-bounded event formats, research and intelligence, decision resources, executive needs, topics, audiences, industries, and geographies.</p><blockquote>Role and audience mappings identify relevant controlled vocabulary. They do not assert that every organization in a cohort offers every mapped format, resource, or outcome.</blockquote><h2>Role and audience mappings</h2><div class="grid">${mappingCards}</div><h2>Questions this dataset can answer</h2><h3>What is an executive community?</h3><p>${esc(executiveCommunityDefinition)}</p><h3>What organizations serve CFOs?</h3><p><a href="cfo-ecosystem.html">${cfoEntities.length} canonical organizations are classified as serving CFOs.</a></p><h3>Which organizations run CISO events?</h3>${entityAnswerList(cisoEventOrganizations)}<h3>Which organizations publish executive benchmarks?</h3>${entityAnswerList(benchmarkPublishers)}<h3>Which organizations serve private equity operating partners?</h3>${entityAnswerList(operatingPartnerOrganizations)}<h3>Which organizations provide CMO networks?</h3>${entityAnswerList(cmoNetworkOrganizations)}<h3>What types of executive events exist?</h3><p>${semantic.event_formats.map(item=>esc(item.label)).join(' · ')}</p><h3>Which organizations provide executive research?</h3>${entityAnswerList(executiveResearchPublishers)}${taxonomySection('Community and membership formats',semantic.community_formats)}${taxonomySection('Event formats',semantic.event_formats)}${taxonomySection('Research and intelligence',semantic.intelligence_types)}${taxonomySection('Frameworks and decision resources',semantic.resource_types)}${taxonomySection('Executive needs and outcomes',semantic.executive_needs)}${taxonomySection('Executive priorities and topics',semantic.topics)}${taxonomySection('Additional audiences',semantic.audiences)}<section><h2>Canonical aliases</h2><p>Near-synonyms resolve to one term rather than creating duplicate categories.</p><div class="table-wrap"><table><thead><tr><th>Alias</th><th>Dimension</th><th>Canonical ID</th></tr></thead><tbody>${aliasRows}</tbody></table></div></section><h2>Machine-readable files</h2><div class="download"><a href="data/taxonomy.json">Taxonomy JSON</a><a href="data/taxonomy-aliases.json">Alias JSON</a><a href="data/role-mappings.json">Role mappings JSON</a><a href="data/semantic-relationships.json">Semantic relationships JSON</a></div><script type="application/ld+json">${faqLd}</script></section>`;
await write('docs/taxonomy.html',shell('Taxonomy',taxonomyBody,'Controlled definitions, role mappings and evidence-backed answers for CXO formats, intelligence, needs, topics and audiences.','Taxonomy'));

await write('docs/methodology.html',shell('Methodology',`<section class="prose"><div class="eyebrow">TRUST AND GOVERNANCE</div><h1>Methodology</h1><h2>Classification model</h2><p>Organizations are classified independently across executive roles, provider types, community formats, event formats, intelligence types, resources, executive needs, topics, audiences, and geographies. A multi-category organization retains one canonical entity record.</p><h2>Controlled vocabulary</h2><p>Every semantic term has a stable ID and neutral definition. Closely related phrases resolve through the alias registry to one canonical concept unless they represent a material functional distinction. Community formats describe ongoing structures; event formats describe time-bounded gatherings; first-party research remains distinct from editorial commentary.</p><p><a href="taxonomy.html">Review the controlled taxonomy, aliases and role mappings.</a></p><h2>Evidence requirement</h2><p>Entity associations require reasonable evidence from official organization, event, research, regulatory, government, or reputable third-party sources. A passing keyword mention is insufficient. Semantic relationship exports retain the evidence URLs used for each classified field.</p><h2>Multi-category organizations</h2><p>An organization may serve multiple roles or appear in multiple dimensions without creating duplicate entity records. Missing associations remain unknown and are not inferred from a company name or isolated article mention.</p><h2>Indexability gate</h2><p>Arbitrary filter combinations remain application state. A canonical page is created only when it has stable intent, enough substantive entities, distinct analysis, and durable value. Dataset v${DATASET_VERSION} adds one substantive taxonomy authority page; it does not create role-format-topic combination pages.</p><h2>Commercial neutrality</h2><p>Inclusion does not constitute endorsement. Commercial relationships do not influence inclusion, ranking, scoring, descriptions, or category placement.</p><h2>Versioning and updates</h2><p>Schema and dataset versions are published in exports. Stable IDs do not change without a documented migration. Taxonomy additions and aliases are recorded in the taxonomy changelog; breaking entity-schema changes require a schema-version update.</p></section>`));
const added=expansion.entities.filter(item=>item.status==='added');const unresolved=expansion.entities.filter(item=>item.status==='unresolved');
const reportRows=items=>items.map(item=>`<tr><td>${esc(item.name)}</td><td>${esc(item.priority||'')}</td><td>${esc(item.status)}</td><td>${esc(item.reason||item.relationship_notes||'Verified from the official organization website.')}</td></tr>`).join('');
await write('docs/reconciliation-report.html',shell('Expansion Reconciliation Report',`<section class="prose wide"><div class="eyebrow">DATASET EXPANSION AUDIT</div><h1>Organization reconciliation report</h1><p>Every supplied organization or alias was assigned a visible state. Priority indicates editorial research order, not rank, quality, sponsorship, or endorsement.</p><div class="stats compact"><div><strong>51</strong><span>Organizations before</span></div><div><strong>${entities.length}</strong><span>Organizations after</span></div><div><strong>${added.length}</strong><span>New canonical entities</span></div></div><h2>Duplicates and aliases resolved</h2><ul>${expansion.duplicate_aliases.map(item=>`<li><b>${esc(item.supplied)}</b> → ${esc(item.canonical)}</li>`).join('')}</ul><h2>Added</h2><div class="table-wrap"><table><thead><tr><th>Organization</th><th>Priority</th><th>Status</th><th>Resolution</th></tr></thead><tbody>${reportRows(added)}</tbody></table></div><h2>Unresolved</h2><p>These names remain in the research queue because assigning a canonical entity without further evidence would risk a false match.</p><div class="table-wrap"><table><thead><tr><th>Supplied name</th><th>Priority</th><th>Status</th><th>Reason</th></tr></thead><tbody>${reportRows(unresolved)}</tbody></table></div><h2>Validation statement</h2><p><b>Every name supplied in the expansion brief has been accounted for</b> as an added canonical entity, merged alias, repeated multi-category reference, or unresolved research item. No name was silently omitted.</p></section>`,'Audit trail for the August 2026 CXO Ecosystem Index organization expansion.'));
const resolutionRows=resolutionV050.map(item=>`<tr><td>${esc(item.original)}</td><td>${esc(item.canonical)}</td><td><a href="https://${esc(item.domain)}">${esc(item.domain)}</a></td><td>${esc(item.result)}</td><td>${esc(item.category)}</td><td>${esc(item.confidence)}</td></tr>`).join('');
await write('docs/v050-report.html',shell('v050 Report',`<section class="prose wide"><div class="eyebrow">RELEASE AUDIT</div><h1>v0.5.0 Fact Depth & Entity Resolution</h1><div class="stats compact"><div><strong>175</strong><span>Organizations before</span></div><div><strong>${entities.length}</strong><span>Organizations after</span></div><div><strong>${s.sourced_facts}</strong><span>Sourced facts</span></div><div><strong>${s.facts_per_entity}</strong><span>Facts per entity</span></div><div><strong>${s.primary_source_coverage}%</strong><span>Primary-source coverage</span></div></div><h2>Former unresolved entities</h2><p>All 18 former unresolved names now have an explicit canonical resolution. Claims are limited to what the cited official source supports.</p><div class="table-wrap"><table><thead><tr><th>Original</th><th>Canonical entity</th><th>Domain</th><th>Resolution</th><th>Category</th><th>Confidence</th></tr></thead><tbody>${resolutionRows}</tbody></table></div><h2>Fact methodology</h2><p>A sourced fact is one explicit field/value assertion connected to at least one source ID and a last-verified date. Array values such as executive roles and provider categories count individually because each is independently queryable. Missing values are omitted. Volatile values require an as-of date and are not inferred.</p></section>`,'v0.5.0 release report covering fact depth and resolution of 18 former unresolved organizations.','v0.5.0 Fact Depth Report'));
const downloadDistributions=[['Entities JSON','application/json','entities.json'],['Entities CSV','text/csv','entities.csv'],['Facts JSON','application/json','facts.json'],['Sources JSON','application/json','sources.json'],['Organization Relationships JSON','application/json','relationships.json'],['Semantic Relationships JSON','application/json','semantic-relationships.json'],['Semantic Relationship Schema','application/schema+json','semantic-relationship.schema.json'],['Knowledge Graph JSON','application/json','knowledge-graph.json'],['Search Index JSON','application/json',searchIndexFile],['Taxonomy JSON','application/json','taxonomy.json'],['Taxonomy Aliases JSON','application/json','taxonomy-aliases.json'],['Role Mappings JSON','application/json','role-mappings.json'],['Definitions JSON','application/json','definitions.json'],['Intelligence JSON','application/json','intelligence.json'],['Benchmarks JSON','application/json','benchmarks.json'],['Market Maps JSON','application/json','market-maps.json'],['Comparisons JSON','application/json','comparisons.json'],['Build Manifest JSON','application/json','build-manifest.json'],['Current Release Manifest JSON','application/json','latest.json']];
