await write('docs/data.html',shell('Data',`<section class="prose wide"><div class="eyebrow">OPEN DATA AUTHORITY HUB</div><h1>CXO Ecosystem Index data</h1><p>Canonical and derived exports are rebuilt from validated source records for every release.</p><div class="stats compact"><div><strong>${s.entities}</strong><span>Organizations</span></div><div><strong>${s.sourced_facts}</strong><span>Sourced facts</span></div><div><strong>${sourceRegistry.length}</strong><span>Canonical sources</span></div><div><strong>${knowledgeGraph.sourced_relationship_count}</strong><span>Organization relationships</span></div><div><strong>${semanticRelationships.length}</strong><span>Semantic relationships</span></div><div><strong>${derivedMetricCount}</strong><span>Derived metrics</span></div></div><h2>Current release</h2><dl><dt>Dataset version</dt><dd>${DATASET_VERSION}</dd><dt>Entity schema version</dt><dd>${SCHEMA_VERSION}</dd><dt>Derived intelligence schema</dt><dd>1.2.0</dd><dt>Last dataset update</dt><dd>${CALCULATED_AT}</dd><dt>Build commit</dt><dd><code>${buildCommit}</code></dd><dt>Release fingerprint</dt><dd><code>${releaseFingerprint}</code></dd><dt>Creator and publisher</dt><dd>Open Future Forum</dd><dt>License</dt><dd>MIT</dd><dt>Coverage</dt><dd>Representative dataset; comprehensive global coverage is not claimed.</dd></dl><p><a href="data/latest.json">Current Release Manifest</a> is provided for programmatic version discovery, debugging, provenance and external data consumers. It is not a search-engine recrawl mechanism.</p><h2>Downloads</h2><div class="download">${downloadLinks}</div><h2>Analytical cohort downloads</h2><div class="download">${cohortLinks}</div><h2>Methods, quality and citation</h2><div class="download"><a href="taxonomy.html">Controlled taxonomy</a><a href="methodology.html">Methodology</a><a href="data-quality.html">Data quality dashboard</a><a href="intelligence/">Intelligence</a><a href="CITATION.cff">Citation metadata</a><a href="reports/search-console-handoff.json">Search Console handoff</a><a href="https://github.com/OpenFutureForum/cxo-ecosystem-index">Repository</a></div><h2>Fact and relationship model</h2><p>Each source-linked fact records a field, value, source ID, and verification or as-of date. Organization-to-organization relationships remain distinct from evidence-linked semantic relationships such as <code>serves_role</code>, <code>offers_event_format</code>, <code>publishes_intelligence</code>, and <code>addresses_topic</code>. Derived reciprocal edges and metrics are explicitly marked.</p><h2>Historical implementation reports</h2><p><a href="reconciliation-report.html">Expansion reconciliation report</a> · <a href="v050-report.html">v0.5 fact-depth report</a></p><script type="application/ld+json">${datasetLd}</script></section>`,'Download the current CXO Ecosystem Index entities, facts, sources, relationships, knowledge graph, taxonomy, search index and intelligence datasets.','Data'));

const urls=['','cxo-ecosystems.html','cfo-ecosystem.html',...rolePages.map(group=>`${slug(group.label)}-ecosystem.html`),'providers/','intelligence/','industries/','data-quality.html','intelligence/silicon-valley-cxo-ecosystem.html','cfo-guides.html',...cfoGuides.map(g=>`guides/${g.slug}.html`),...providerGroups.map(group=>`providers/${group.id}.html`),...formatGroups.map(group=>`formats/${group.id}.html`),...intelligence.market_maps.map(item=>`intelligence/${item.id}.html`),...intelligence.comparisons.map(item=>`intelligence/compare-${item.comparison_id}.html`),...intelligence.benchmarks.filter(item=>item.id!=='data-quality').map(item=>`intelligence/${item.id}.html`),...industryGroups.map(group=>`industries/${slug(group.industry)}.html`),'reconciliation-report.html','v050-report.html','taxonomy.html','methodology.html','data.html',...entities.map(e=>`entities/${e.slug}.html`)];
const maxDate=values=>values.filter(value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')).sort().at(-1)||null;
const entityModified=entity=>maxDate([entity?.last_verified,...(entity?.facts||[]).flatMap(fact=>[fact.last_verified,fact.as_of])]);
const cohortModified=members=>maxDate(members.map(entityModified));
const datasetLastmod=cohortModified(entities);
const lastmodFor=url=>{
 if(url.startsWith('entities/'))return entityModified(entities.find(item=>`${item.slug}.html`===url.slice(9)));
 if(url.startsWith('guides/'))return cfoGuides.find(guide=>`${guide.slug}.html`===url.slice(7))?.updated||null;
 if(['methodology.html','reconciliation-report.html','v050-report.html'].includes(url))return null;
 if(url==='cfo-guides.html')return maxDate(cfoGuides.map(guide=>guide.updated));
 if(url==='intelligence/silicon-valley-cxo-ecosystem.html')return cohortModified(siliconValleyEntities);
 if(url.startsWith('providers/')&&url!=='providers/'){const id=url.slice(10,-5);return cohortModified(providerGroups.find(group=>group.id===id)?.entities||[]);}
 if(url.startsWith('formats/')){const id=url.slice(8,-5);return cohortModified(formatGroups.find(group=>group.id===id)?.entities||[]);}
 if(url.startsWith('industries/')&&url!=='industries/'){const id=url.slice(11,-5);return cohortModified(industryGroups.find(group=>slug(group.industry)===id)?.entities||[]);}
 if(url.startsWith('intelligence/')){const id=url.slice(13,-5);const map=intelligence.market_maps.find(item=>item.id===id);if(map)return cohortModified(map.entity_ids.map(entityId=>byId.get(entityId)));const comparison=intelligence.comparisons.find(item=>`compare-${item.comparison_id}`===id);if(comparison)return cohortModified(comparison.entity_ids.map(entityId=>byId.get(entityId)));return datasetLastmod;}
 if(url==='cfo-ecosystem.html')return cohortModified(cfoEntities);
 const role=rolePages.find(group=>`${slug(group.label)}-ecosystem.html`===url);if(role)return cohortModified(entities.filter(entity=>role.roles.some(item=>entity.cxo_roles.includes(item))));
 return datasetLastmod;
};
