await write('docs/llms.txt',`# CXO Ecosystem Index\n\nIndependent structured index maintained by Open Future Forum. Inclusion does not imply endorsement.\n\nRelease: ${releaseLabel}\nEntity schema: ${SCHEMA_VERSION}\nLast dataset update: ${CALCULATED_AT}\nRelease fingerprint: ${releaseFingerprint}\n\nThe Index maps:\n- CXO roles and additional executive or investment audiences\n- organizations and provider types\n- ongoing communities, networks and membership formats\n- time-bounded event formats\n- research, benchmarks and other intelligence types\n- frameworks and decision resources\n- executive needs and outcomes\n- leadership priorities and topics\n- industries and geographies\n\nClassification policy:\n- every entity association requires evidence\n- missing values remain unknown\n- community formats are distinct from event formats\n- first-party research is distinct from editorial commentary\n- arbitrary role/format/topic combinations remain filters, not indexable pages\n\nCanonical resources:\n- Homepage: https://openfutureforum.github.io/cxo-ecosystem-index/\n- Taxonomy and AEO answers: https://openfutureforum.github.io/cxo-ecosystem-index/taxonomy.html\n- Data authority hub: https://openfutureforum.github.io/cxo-ecosystem-index/data.html\n- Methodology: https://openfutureforum.github.io/cxo-ecosystem-index/methodology.html\n- Intelligence: https://openfutureforum.github.io/cxo-ecosystem-index/intelligence/\n- Build manifest: https://openfutureforum.github.io/cxo-ecosystem-index/data/build-manifest.json\n- Current Release Manifest: https://openfutureforum.github.io/cxo-ecosystem-index/data/latest.json\n- Entities: https://openfutureforum.github.io/cxo-ecosystem-index/data/entities.json\n- Facts: https://openfutureforum.github.io/cxo-ecosystem-index/data/facts.json\n- Sources: https://openfutureforum.github.io/cxo-ecosystem-index/data/sources.json\n- Organization relationships: https://openfutureforum.github.io/cxo-ecosystem-index/data/relationships.json\n- Semantic relationships: https://openfutureforum.github.io/cxo-ecosystem-index/data/semantic-relationships.json\n- Knowledge graph: https://openfutureforum.github.io/cxo-ecosystem-index/data/knowledge-graph.json\n- Taxonomy: https://openfutureforum.github.io/cxo-ecosystem-index/data/taxonomy.json\n- Taxonomy aliases: https://openfutureforum.github.io/cxo-ecosystem-index/data/taxonomy-aliases.json\n- Role mappings: https://openfutureforum.github.io/cxo-ecosystem-index/data/role-mappings.json\n- Fingerprinted search index: https://openfutureforum.github.io/cxo-ecosystem-index/data/${searchIndexFile}\n- Citation: https://openfutureforum.github.io/cxo-ecosystem-index/CITATION.cff\n- Repository: https://github.com/OpenFutureForum/cxo-ecosystem-index\n`);
const testFiles=await fs.readdir(path.join(root,'tests'));let testCount=0;for(const file of testFiles.filter(file=>file.endsWith('.test.mjs'))){const source=await fs.readFile(path.join(root,'tests',file),'utf8');testCount+=(source.match(/^test\s*\(/gm)||[]).length;}
const readmePath=path.join(root,'README.md');const readme=await fs.readFile(readmePath,'utf8');const statusBlock=`<!-- DATASET_STATUS_START -->\n## Current dataset\n\n| Measure | Current value |\n|---|---:|\n| Release | ${DATASET_VERSION} |\n| Entity schema | ${SCHEMA_VERSION} |\n| Canonical organizations | ${s.entities.toLocaleString('en-US')} |\n| Sourced facts | ${s.sourced_facts.toLocaleString('en-US')} |\n| Canonical sources | ${sourceRegistry.length.toLocaleString('en-US')} |\n| Sourced relationships | ${knowledgeGraph.sourced_relationship_count} |\n| Derived reciprocal relationships | ${knowledgeGraph.derived_reciprocal_count} |\n| Derived metrics | ${derivedMetricCount} |\n| Tests | ${testCount} |\n<!-- DATASET_STATUS_END -->`;await fs.writeFile(readmePath,readme.replace(/<!-- DATASET_STATUS_START -->[\s\S]*?<!-- DATASET_STATUS_END -->/,statusBlock));
